def ref(path,needle,why):
 p=R/path;b=p.read_bytes();s=b.decode();assert needle in s,(path,needle)
 at=s.index(needle);line=s[:at].count('\n')+1
 inputs[path]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
 rid='A'+str(len(refs)+1).zfill(2);refs.append({'id':rid,'path':path,'line':line,'needle':needle,'excerpt':s[max(0,at-35):at+min(len(needle)+110,260)],'observation':why});return rid
